<script setup lang="ts">
const client=useClient()
import { HttpError } from '@zedflow/sdk'

import { useClient } from '@zedflow/vue'

import { useReloadDrafts, managedReload } from '../../composables/reloadState'
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { Plus, Save, Code2, Trash2, Copy } from 'lucide-vue-next'
import ContextExpressionEditor from './ContextExpressionEditor.vue'
import ContextTypeEditor from './ContextTypeEditor.vue'
import AppDialog from '../AppDialog.vue'
import { cloneContext, contextId, textExpression } from '../../contextEngine'
import type { ContextLibrary, ContextLibraryFile, ContextType } from '@zedflow/sdk'
const props=defineProps<{workspaceId:string;active:boolean;types:Record<string,ContextType>}>()
const emit=defineEmits<{saved:[file:ContextLibraryFile]}>()
interface Draft{key:string;file?:ContextLibraryFile;library:ContextLibrary;saved:string;selected:string;catalog:'projections'|'subprograms';error:string;notice:string;pending:boolean}
interface Session{files:ContextLibraryFile[];drafts:Record<string,Draft>;selected:string;error:string}
const sessions=reactive<Record<string,Session>>({})
  useReloadDrafts('library-drafts',sessions)
function blank():Draft{return{key:contextId('library'),library:{projections:{},subprograms:{}},saved:'',selected:'',catalog:'projections',error:'',notice:'',pending:false}}
function state(){return sessions[props.workspaceId]||=( {files:[],drafts:{new:blank()},selected:'new',error:''})}
const session=computed(state),draft=computed(()=>session.value.drafts[session.value.selected])
const functions=computed(()=>draft.value.library[draft.value.catalog]),selected=computed(()=>functions.value[draft.value.selected])
const functionName=ref(''),parameterName=ref(''),sourceOpen=ref(false),reloadOpen=ref(false)
const dirty=computed(()=>JSON.stringify(draft.value.library)!==draft.value.saved)
let refreshIntent=0
async function refresh(){const id=props.workspaceId,current=state(),intent=++refreshIntent;if(!id)return;try{const files=await client.context.listLibraries({workspaceId:id});if(intent===refreshIntent)current.files=Array.isArray(files)?files:[]}catch(error){current.error=String(error instanceof Error?error.message:error)}}
async function open(key:string,force=false){const current=state(),id=props.workspaceId;if(!key)return;if(current.drafts[key]&&!force){current.selected=key;return}current.selected=key;const value=current.drafts[key]||=blank();value.pending=true;try{const file=await client.context.readLibrary(key,{workspaceId:id});value.file=file;value.key=file.key;value.library=cloneContext(file.library||{projections:{},subprograms:{}});value.saved=JSON.stringify(value.library);value.catalog=Object.keys(value.library.projections).length?'projections':'subprograms';value.selected=Object.keys(value.library[value.catalog])[0]||'';value.error=file.diagnostics.map(item=>item.message).join('; ')}catch(error){value.error=String(error instanceof Error?error.message:error)}finally{value.pending=false;reloadOpen.value=false}}
function create(copy=false){const next=blank();if(copy)next.library=cloneContext(draft.value.library);const key=`draft:${next.key}`;session.value.drafts[key]=next;session.value.selected=key}
function add(){const name=functionName.value.trim();if(!/^[a-zA-Z0-9_-]{1,160}$/.test(name)||Object.hasOwn(functions.value,name)){draft.value.error='Utilisez un nom unique : lettres, chiffres, tiret ou underscore.';return}functions.value[name]={parameters:{},output:{kind:'text'},body:textExpression()};draft.value.selected=name;functionName.value='';draft.value.error=''}
function addParameter(){const name=parameterName.value.trim();if(!selected.value||!name||Object.hasOwn(selected.value.parameters,name)){draft.value.error='Choisissez un nom de paramètre unique.';return}selected.value.parameters[name]={kind:'text'};parameterName.value=''}
async function save(){const current=state(),value=draft.value,slot=current.selected,id=props.workspaceId;if(value.pending)return;value.pending=true;value.error='';value.notice='';const library=cloneContext(value.library),key=value.key;try{const file=await client.context.saveLibrary({workspaceId:id,key,library,types:props.types,...(value.file?{expectedHash:value.file.hash}:{})});value.file=file;value.saved=JSON.stringify(library);value.notice='Bibliothèque enregistrée en Rust';current.files=[...current.files.filter(item=>item.key!==file.key),file];if(slot!==file.key){current.drafts[file.key]=value;delete current.drafts[slot];if(current.selected===slot)current.selected=file.key}emit('saved',file)}catch(error){value.error=String(error instanceof Error?error.message:error);if(error instanceof HttpError&&error.status===409)value.error+=' · Le brouillon est conservé : rechargez ou dupliquez la bibliothèque.'}finally{value.pending=false}}
watch(()=>[props.workspaceId,props.active],()=>{if(props.active)void refresh()},{immediate:true})
watch(()=>draft.value.catalog,()=>{draft.value.selected=Object.keys(functions.value)[0]||''})
function keys(event:KeyboardEvent){if(props.active&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();event.stopPropagation();void save()}}
const beforeUnload=(event:BeforeUnloadEvent)=>{if(!managedReload&&Object.values(sessions).some(session=>Object.values(session.drafts).some(draft=>JSON.stringify(draft.library)!==draft.saved&&(Object.keys(draft.library.projections).length||Object.keys(draft.library.subprograms).length))))event.preventDefault()}
window.addEventListener('beforeunload',beforeUnload);onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload))

</script>
<template>
  <section @keydown="keys" class="ctx-function-library" aria-label="Éditeur de bibliothèques"><header class="ctx-function-toolbar"><label>Bibliothèque ouverte<select aria-label="Bibliothèque ouverte" :value="session.selected" @change="open(($event.target as HTMLSelectElement).value)"><option v-for="file in session.files" :key="file.key" :value="file.key">{{file.key}}</option><option v-for="(item,key) in session.drafts" v-show="!item.file" :key="key" :value="key">{{item.key}} · brouillon</option></select></label><button @click="create()"><Plus :size="13"/>Nouvelle bibliothèque</button><button @click="create(true)" aria-label="Dupliquer la bibliothèque"><Copy :size="13"/></button><button :disabled="!draft.file?.source" aria-label="Afficher le Rust de la bibliothèque" @click="sourceOpen=true"><Code2 :size="13"/></button><button :disabled="draft.pending||(!draft.file?.library&&!!draft.file)" @click="save"><Save :size="13"/>Enregistrer la bibliothèque</button><button v-if="draft.file" :disabled="draft.pending" @click="reloadOpen=true">Recharger</button></header><div v-if="draft.error||session.error" role="alert" class="ctx-alert ctx-error">{{draft.error||session.error}}</div><div v-if="draft.notice" role="status" class="ctx-alert">{{draft.notice}}</div><div class="ctx-function-layout"><aside><label>Identifiant du fichier<input v-model="draft.key" :readonly="!!draft.file" aria-label="Identifiant de la bibliothèque"/></label><small>{{dirty?'Brouillon modifié':draft.file?.hash.slice(0,12)}} · .zedflow/context/libraries</small><label>Famille<select v-model="draft.catalog" aria-label="Famille de fonctions"><option value="projections">Projections nommées</option><option value="subprograms">Sous-programmes purs</option></select></label><button v-for="(_,name) in functions" :key="name" class="ctx-function-row" :class="{selected:draft.selected===name}" @click="draft.selected=name">{{name}}</button><div class="ctx-add-field"><input v-model="functionName" aria-label="Nom de la fonction" placeholder="Nouvelle fonction" @keydown.enter.prevent="add"/><button aria-label="Ajouter une fonction" @click="add"><Plus :size="13"/></button></div><p class="ctx-hint">Les fonctions lisent leurs paramètres. Elles ne disposent d’aucune ressource ou capacité implicite.</p></aside><div class="ctx-function-body"><template v-if="selected"><header><h2>{{draft.selected}}</h2><button aria-label="Supprimer la fonction" @click="delete functions[draft.selected];draft.selected=Object.keys(functions)[0]||''"><Trash2 :size="13"/></button></header><fieldset :disabled="draft.pending||(!draft.file?.library&&!!draft.file)"><details class="ctx-function-signature" open><summary>Paramètres et sortie</summary><div v-for="(_,name) in selected.parameters" :key="name" class="ctx-field"><ContextTypeEditor v-model="selected.parameters[name]" :label="`Paramètre ${name}`" :names="Object.keys(types)"/><button :aria-label="`Retirer le paramètre ${name}`" @click="delete selected.parameters[name]">×</button></div><div class="ctx-add-field"><input v-model="parameterName" aria-label="Nom du paramètre" placeholder="Nouveau paramètre" @keydown.enter.prevent="addParameter"/><button aria-label="Ajouter le paramètre" @click="addParameter"><Plus :size="13"/></button></div><ContextTypeEditor v-model="selected.output" label="Type de sortie" :names="Object.keys(types)"/></details><ContextExpressionEditor v-model="selected.body" :resources="{}" :variables="Object.keys(selected.parameters)" :types="types" label="Corps de la fonction"/></fieldset></template><p v-else class="ctx-hint">Ajoutez une projection ou un sous-programme, puis composez son résultat avec les blocs d’expression.</p></div></div><AppDialog v-model:open="sourceOpen" title="Rust de la bibliothèque" wide><p v-if="dirty" class="ctx-hint">Source de la dernière version enregistrée ; le brouillon contient des modifications.</p><pre class="source-preview">{{draft.file?.source}}</pre></AppDialog><AppDialog v-model:open="reloadOpen" title="Recharger la bibliothèque"><p>Remplacer ce brouillon par la version du fichier Rust ?</p><footer><button @click="reloadOpen=false">Conserver le brouillon</button><button @click="open(draft.file!.key,true)">Recharger depuis le disque</button></footer></AppDialog></section>
</template>
